import unittest; import random; from sorting import sort_by_length
class TestSortByLength(unittest.TestCase):
    def test_fuzz(self):
        for _ in range(500):
            words = [random.choice(['a', 'b', 'c']) * i for i in range(1, 10)]
            self.assertEqual(sort_by_length(words), sorted(words, key=lambda w: (len(w), w)))

if __name__ == '__main__':
    unittest.main()

